-- =============================================================================
-- Biblioteca inicial de exercícios (técnica padrão de execução).
-- Mídias (imagens/vídeos) serão enviadas pelo admin em /admin/exercicios para o
-- armazenamento de arquivos (definido na Etapa 4) — não há mídias fictícias.
-- =============================================================================
insert into public.exercises (slug, name, primary_muscles, secondary_muscles, equipment, mechanics, level, instructions, tips) values
-- PEITO -----------------------------------------------------------------------
('supino-reto-barra', 'Supino reto com barra', '{peito}', '{triceps,ombros}', 'barra', 'composto', 'iniciante',
 '{"Deite no banco com os olhos alinhados à barra e os pés firmes no chão.","Segure a barra com pegada um pouco mais larga que os ombros.","Retraia as escápulas e mantenha o peito elevado.","Desça a barra controladamente até tocar a parte média/inferior do peito.","Empurre a barra de volta até estender os cotovelos, sem perder a retração escapular."}',
 '{"Mantenha os punhos alinhados sobre os cotovelos.","Use um parceiro de segurança ao trabalhar com cargas altas."}'),
('supino-inclinado-halteres', 'Supino inclinado com halteres', '{peito}', '{ombros,triceps}', 'halteres', 'composto', 'iniciante',
 '{"Ajuste o banco entre 30° e 45° de inclinação.","Sente-se com um halter em cada mão apoiado nas coxas e deite levando-os à altura do peito.","Empurre os halteres para cima até quase estender os cotovelos.","Desça de forma controlada até sentir alongamento no peito, com cotovelos levemente abaixo da linha dos ombros."}',
 '{"Evite bater os halteres no topo.","Inclinações muito altas transferem o trabalho para os ombros."}'),
('supino-reto-halteres', 'Supino reto com halteres', '{peito}', '{triceps,ombros}', 'halteres', 'composto', 'iniciante',
 '{"Deite no banco reto com um halter em cada mão na altura do peito.","Mantenha as escápulas retraídas e os pés apoiados.","Empurre os halteres para cima até quase estender os cotovelos.","Retorne de forma controlada até a altura do peito."}',
 '{"Mantenha os antebraços perpendiculares ao chão durante o movimento."}'),
('crucifixo-halteres', 'Crucifixo com halteres', '{peito}', '{ombros}', 'halteres', 'isolado', 'iniciante',
 '{"Deite no banco reto com os halteres acima do peito, palmas voltadas uma para a outra.","Mantenha os cotovelos levemente flexionados durante todo o movimento.","Abra os braços em arco até sentir alongamento no peito.","Retorne pelo mesmo arco contraindo o peitoral."}',
 '{"Não desça além da amplitude confortável para os ombros."}'),
('crossover-polia', 'Crossover na polia', '{peito}', '{ombros}', 'polia', 'isolado', 'intermediario',
 '{"Posicione as polias na altura alta e segure uma alça em cada mão.","Dê um passo à frente, incline levemente o tronco e mantenha os cotovelos semiflexionados.","Traga as mãos à frente e para baixo, cruzando a linha média do corpo.","Retorne controlando a carga até sentir alongamento no peito."}',
 '{"Ajuste a altura das polias para enfatizar diferentes porções do peitoral."}'),
('flexao-de-bracos', 'Flexão de braços', '{peito}', '{triceps,ombros,abdomen}', 'peso corporal', 'composto', 'iniciante',
 '{"Apoie as mãos no chão um pouco além da largura dos ombros.","Mantenha o corpo alinhado da cabeça aos calcanhares, com abdômen contraído.","Flexione os cotovelos descendo o peito em direção ao chão.","Empurre o chão até estender os cotovelos."}',
 '{"Para facilitar, apoie os joelhos ou eleve as mãos em um banco."}'),
('peck-deck', 'Voador (peck deck)', '{peito}', '{ombros}', 'máquina', 'isolado', 'iniciante',
 '{"Ajuste o assento para que as manoplas fiquem na altura do peito.","Sente-se com as costas apoiadas e segure as manoplas.","Feche os braços à frente contraindo o peitoral.","Retorne lentamente até sentir alongamento, sem deixar as placas baterem."}',
 '{"Mantenha os ombros abaixados e afastados das orelhas."}'),
-- COSTAS ----------------------------------------------------------------------
('puxada-frente-polia', 'Puxada frontal na polia', '{costas}', '{biceps,ombros}', 'polia', 'composto', 'iniciante',
 '{"Sente-se e ajuste o apoio das coxas.","Segure a barra com pegada pronada um pouco mais larga que os ombros.","Incline levemente o tronco para trás e puxe a barra em direção à parte superior do peito.","Leve os cotovelos para baixo e para trás, aproximando as escápulas.","Retorne controlando até estender os braços."}',
 '{"Evite puxar a barra atrás da nuca.","Não use impulso do tronco para completar o movimento."}'),
('barra-fixa', 'Barra fixa', '{costas}', '{biceps,ombros,abdomen}', 'barra fixa', 'composto', 'intermediario',
 '{"Segure a barra com pegada pronada na largura dos ombros ou um pouco mais aberta.","Inicie pendurado com os braços estendidos e o abdômen contraído.","Puxe o corpo para cima até o queixo passar a barra.","Desça de forma controlada até estender os braços."}',
 '{"Use elástico de assistência ou a versão assistida em máquina se necessário."}'),
('remada-curvada-barra', 'Remada curvada com barra', '{costas}', '{biceps,lombar,ombros}', 'barra', 'composto', 'intermediario',
 '{"Segure a barra com pegada pronada na largura dos ombros.","Flexione levemente os joelhos e incline o tronco à frente mantendo a coluna neutra.","Puxe a barra em direção ao abdômen, levando os cotovelos para trás.","Contraia as costas no topo e desça controlando."}',
 '{"Mantenha a coluna neutra durante toda a série.","Reduza a carga se o tronco começar a subir."}'),
('remada-baixa-polia', 'Remada baixa na polia', '{costas}', '{biceps,ombros}', 'polia', 'composto', 'iniciante',
 '{"Sente-se com os pés apoiados e joelhos levemente flexionados.","Segure o triângulo com o tronco ereto.","Puxe a pegada em direção ao abdômen, aproximando as escápulas.","Retorne estendendo os braços sem arredondar a coluna."}',
 '{"Evite balançar o tronco para frente e para trás."}'),
('remada-unilateral-halter', 'Remada unilateral com halter', '{costas}', '{biceps,ombros}', 'halteres', 'composto', 'iniciante',
 '{"Apoie um joelho e a mão do mesmo lado em um banco, com a coluna neutra.","Segure o halter com o braço estendido.","Puxe o halter em direção ao quadril, mantendo o cotovelo próximo ao corpo.","Desça controlando até estender o braço."}',
 '{"Evite girar o tronco para levantar a carga."}'),
('pulldown-braco-estendido', 'Pulldown com braços estendidos', '{costas}', '{ombros,triceps}', 'polia', 'isolado', 'intermediario',
 '{"Fique em pé de frente para a polia alta segurando a barra com braços estendidos.","Incline levemente o tronco à frente.","Leve a barra em arco até a altura das coxas, mantendo os cotovelos quase estendidos.","Retorne controlando até a altura dos olhos."}',
 '{"O movimento acontece nos ombros; não flexione os cotovelos."}'),
('levantamento-terra', 'Levantamento terra', '{costas,posteriores,gluteos}', '{lombar,quadriceps,antebracos}', 'barra', 'composto', 'avancado',
 '{"Posicione os pés na largura do quadril com a barra sobre o meio dos pés.","Segure a barra logo fora das pernas, quadril acima dos joelhos e coluna neutra.","Contraia o abdômen, estenda os joelhos e o quadril simultaneamente, mantendo a barra próxima ao corpo.","Finalize em pé com quadril estendido, sem hiperestender a lombar.","Desça a barra controlando o movimento pelo quadril."}',
 '{"Aprenda o padrão com cargas leves e acompanhamento profissional.","Não arredonde a coluna durante o movimento."}'),
-- OMBROS ----------------------------------------------------------------------
('desenvolvimento-halteres', 'Desenvolvimento com halteres', '{ombros}', '{triceps}', 'halteres', 'composto', 'iniciante',
 '{"Sente-se com as costas apoiadas e os halteres na altura dos ombros.","Empurre os halteres para cima até quase estender os cotovelos.","Desça controlando até a altura das orelhas/ombros."}',
 '{"Evite arquear excessivamente a lombar."}'),
('desenvolvimento-maquina', 'Desenvolvimento na máquina', '{ombros}', '{triceps}', 'máquina', 'composto', 'iniciante',
 '{"Ajuste o banco para que as manoplas fiquem na altura dos ombros.","Empurre as manoplas para cima até quase estender os cotovelos.","Retorne de forma controlada."}',
 '{"Mantenha as costas apoiadas no encosto."}'),
('elevacao-lateral', 'Elevação lateral com halteres', '{ombros}', '{}', 'halteres', 'isolado', 'iniciante',
 '{"Fique em pé com um halter em cada mão ao lado do corpo.","Com cotovelos levemente flexionados, eleve os braços lateralmente até a altura dos ombros.","Desça lentamente até a posição inicial."}',
 '{"Lidere o movimento pelos cotovelos, não pelas mãos.","Evite usar impulso do tronco."}'),
('elevacao-frontal', 'Elevação frontal com halteres', '{ombros}', '{}', 'halteres', 'isolado', 'iniciante',
 '{"Fique em pé com os halteres à frente das coxas.","Eleve um ou ambos os braços à frente até a altura dos ombros.","Desça controlando."}',
 '{"Mantenha o tronco estável durante todo o movimento."}'),
('crucifixo-inverso', 'Crucifixo inverso', '{ombros}', '{costas}', 'halteres', 'isolado', 'iniciante',
 '{"Incline o tronco à frente com a coluna neutra, halteres pendurados abaixo do peito.","Com cotovelos levemente flexionados, abra os braços lateralmente.","Contraia a parte posterior dos ombros no topo e desça controlando."}',
 '{"Também pode ser feito na máquina voador, sentado de frente para o encosto."}'),
('face-pull', 'Face pull', '{ombros}', '{costas}', 'polia', 'isolado', 'intermediario',
 '{"Ajuste a polia na altura do rosto e use a corda.","Segure a corda com as palmas voltadas para baixo e dê um passo para trás.","Puxe a corda em direção ao rosto, abrindo as mãos e levando os cotovelos para trás e para cima.","Retorne controlando."}',
 '{"Exercício útil para equilíbrio da musculatura posterior dos ombros."}'),
-- BRAÇOS ----------------------------------------------------------------------
('rosca-direta-barra', 'Rosca direta com barra', '{biceps}', '{antebracos}', 'barra', 'isolado', 'iniciante',
 '{"Fique em pé segurando a barra com pegada supinada na largura dos ombros.","Mantenha os cotovelos junto ao corpo.","Flexione os cotovelos levando a barra até a altura dos ombros.","Desça controlando até estender os braços."}',
 '{"Evite balançar o tronco para subir a carga."}'),
('rosca-alternada', 'Rosca alternada com halteres', '{biceps}', '{antebracos}', 'halteres', 'isolado', 'iniciante',
 '{"Fique em pé ou sentado com um halter em cada mão, braços estendidos.","Flexione um cotovelo de cada vez, girando a palma para cima durante a subida.","Desça controlando e alterne os lados."}',
 '{"Mantenha os cotovelos fixos ao lado do corpo."}'),
('rosca-martelo', 'Rosca martelo', '{biceps}', '{antebracos}', 'halteres', 'isolado', 'iniciante',
 '{"Segure os halteres com as palmas voltadas para o corpo.","Flexione os cotovelos mantendo a pegada neutra.","Desça controlando."}',
 '{"Enfatiza braquial e braquiorradial."}'),
('rosca-scott', 'Rosca Scott', '{biceps}', '{}', 'banco scott', 'isolado', 'intermediario',
 '{"Apoie a parte posterior dos braços no banco Scott.","Segure a barra ou halter com pegada supinada.","Flexione os cotovelos até a contração máxima.","Desça lentamente sem estender completamente de forma brusca."}',
 '{"Controle a fase de descida para proteger os cotovelos."}'),
('triceps-polia-barra', 'Tríceps na polia com barra', '{triceps}', '{}', 'polia', 'isolado', 'iniciante',
 '{"Fique de frente para a polia alta segurando a barra com pegada pronada.","Mantenha os cotovelos junto ao corpo.","Estenda os cotovelos empurrando a barra para baixo.","Retorne controlando até cerca de 90° de flexão."}',
 '{"Os cotovelos devem permanecer parados durante o movimento."}'),
('triceps-corda', 'Tríceps na polia com corda', '{triceps}', '{}', 'polia', 'isolado', 'iniciante',
 '{"Segure a corda na polia alta com pegada neutra.","Com os cotovelos fixos ao lado do corpo, estenda os braços.","Afaste as pontas da corda no final do movimento.","Retorne controlando."}',
 '{}'),
('triceps-frances', 'Tríceps francês com halter', '{triceps}', '{}', 'halteres', 'isolado', 'intermediario',
 '{"Sentado ou em pé, segure um halter com as duas mãos acima da cabeça.","Flexione os cotovelos descendo o halter atrás da cabeça.","Estenda os cotovelos retornando à posição inicial."}',
 '{"Mantenha os cotovelos apontados para frente."}'),
('mergulho-paralelas', 'Mergulho nas paralelas', '{triceps,peito}', '{ombros}', 'paralelas', 'composto', 'intermediario',
 '{"Apoie-se nas paralelas com os braços estendidos.","Flexione os cotovelos descendo o corpo até cerca de 90°.","Empurre de volta até estender os braços."}',
 '{"Tronco mais vertical enfatiza o tríceps; inclinado à frente enfatiza o peito.","Use a máquina assistida se necessário."}'),
-- PERNAS ----------------------------------------------------------------------
('agachamento-livre', 'Agachamento livre com barra', '{quadriceps,gluteos}', '{posteriores,lombar,abdomen}', 'barra', 'composto', 'intermediario',
 '{"Posicione a barra sobre o trapézio e afaste os pés na largura dos ombros.","Contraia o abdômen e mantenha o peito aberto.","Flexione quadril e joelhos simultaneamente, descendo com os joelhos alinhados aos pés.","Desça até a profundidade que mantenha a coluna neutra.","Empurre o chão para retornar à posição inicial."}',
 '{"Use as travas de segurança do rack.","Não deixe os joelhos colapsarem para dentro."}'),
('leg-press-45', 'Leg press 45°', '{quadriceps,gluteos}', '{posteriores}', 'máquina', 'composto', 'iniciante',
 '{"Sente-se com as costas e o quadril apoiados no encosto.","Posicione os pés na plataforma na largura dos ombros.","Destrave a plataforma e flexione os joelhos controlando a descida.","Empurre a plataforma sem travar completamente os joelhos no final."}',
 '{"Não deixe o quadril descolar do encosto na descida."}'),
('agachamento-hack', 'Agachamento no hack', '{quadriceps}', '{gluteos}', 'máquina', 'composto', 'iniciante',
 '{"Apoie as costas e os ombros na máquina, pés na plataforma.","Destrave e desça flexionando os joelhos de forma controlada.","Empurre a plataforma retornando à posição inicial."}',
 '{"A posição dos pés altera a ênfase entre quadríceps e glúteos."}'),
('cadeira-extensora', 'Cadeira extensora', '{quadriceps}', '{}', 'máquina', 'isolado', 'iniciante',
 '{"Ajuste o encosto para alinhar o joelho ao eixo da máquina.","Posicione o rolo acima dos tornozelos.","Estenda os joelhos até quase a extensão completa.","Desça controlando."}',
 '{"Evite movimentos bruscos no final da extensão."}'),
('mesa-flexora', 'Mesa flexora', '{posteriores}', '{panturrilhas}', 'máquina', 'isolado', 'iniciante',
 '{"Deite de bruços com o joelho alinhado ao eixo da máquina e o rolo acima dos calcanhares.","Flexione os joelhos levando o rolo em direção aos glúteos.","Retorne controlando."}',
 '{"Mantenha o quadril apoiado no banco."}'),
('cadeira-flexora', 'Cadeira flexora', '{posteriores}', '{}', 'máquina', 'isolado', 'iniciante',
 '{"Sente-se com o joelho alinhado ao eixo da máquina e o rolo atrás dos tornozelos.","Trave as coxas com o apoio superior.","Flexione os joelhos ao máximo e retorne controlando."}',
 '{}'),
('stiff', 'Stiff com barra', '{posteriores,gluteos}', '{lombar}', 'barra', 'composto', 'intermediario',
 '{"Fique em pé segurando a barra à frente das coxas, joelhos levemente flexionados.","Incline o tronco levando o quadril para trás, mantendo a coluna neutra e a barra próxima às pernas.","Desça até sentir alongamento nos posteriores de coxa.","Retorne estendendo o quadril."}',
 '{"O movimento é de quadril; não arredonde as costas."}'),
('afundo-halteres', 'Afundo com halteres', '{quadriceps,gluteos}', '{posteriores}', 'halteres', 'composto', 'iniciante',
 '{"Segure um halter em cada mão ao lado do corpo.","Dê um passo à frente e flexione ambos os joelhos até o joelho de trás se aproximar do chão.","Empurre com a perna da frente para voltar.","Alterne as pernas ou complete as repetições de um lado."}',
 '{"Mantenha o tronco ereto e o joelho da frente alinhado ao pé."}'),
('agachamento-bulgaro', 'Agachamento búlgaro', '{quadriceps,gluteos}', '{posteriores}', 'halteres', 'composto', 'intermediario',
 '{"Apoie o peito do pé de trás em um banco.","Com a perna da frente afastada, desça flexionando o joelho da frente.","Suba empurrando o chão com a perna da frente."}',
 '{"Comece sem carga até dominar o equilíbrio."}'),
('elevacao-pelvica', 'Elevação pélvica com barra', '{gluteos}', '{posteriores}', 'barra', 'composto', 'intermediario',
 '{"Apoie a parte superior das costas em um banco com a barra sobre o quadril (use proteção).","Pés apoiados no chão, joelhos flexionados.","Eleve o quadril até alinhar tronco e coxas, contraindo os glúteos.","Desça controlando."}',
 '{"Evite hiperestender a lombar no topo."}'),
('cadeira-abdutora', 'Cadeira abdutora', '{gluteos}', '{}', 'máquina', 'isolado', 'iniciante',
 '{"Sente-se com as costas apoiadas e as pernas encostadas nas almofadas.","Afaste as pernas contra a resistência.","Retorne controlando."}',
 '{}'),
('panturrilha-em-pe', 'Panturrilha em pé', '{panturrilhas}', '{}', 'máquina', 'isolado', 'iniciante',
 '{"Posicione os ombros sob os apoios e o antepé na plataforma.","Desça os calcanhares até sentir alongamento.","Eleve os calcanhares ao máximo e contraia por um instante."}',
 '{"Faça o movimento completo e controlado."}'),
('panturrilha-sentado', 'Panturrilha sentado', '{panturrilhas}', '{}', 'máquina', 'isolado', 'iniciante',
 '{"Sente-se com o apoio sobre as coxas e o antepé na plataforma.","Desça os calcanhares e depois eleve-os ao máximo."}',
 '{"Enfatiza o músculo sóleo."}'),
-- CORE ------------------------------------------------------------------------
('prancha', 'Prancha', '{abdomen}', '{ombros,gluteos}', 'peso corporal', 'isolado', 'iniciante',
 '{"Apoie os antebraços no chão com os cotovelos abaixo dos ombros.","Estenda as pernas e apoie as pontas dos pés.","Mantenha o corpo alinhado, abdômen e glúteos contraídos, pelo tempo indicado."}',
 '{"Não deixe o quadril cair nem subir demais.","Repetições indicam segundos de sustentação quando prescrito."}'),
('abdominal-supra', 'Abdominal supra', '{abdomen}', '{}', 'peso corporal', 'isolado', 'iniciante',
 '{"Deite com os joelhos flexionados e os pés apoiados.","Cruze os braços no peito ou apoie as mãos levemente atrás da cabeça.","Eleve as escápulas do chão contraindo o abdômen.","Retorne controlando."}',
 '{"Não puxe a cabeça com as mãos."}'),
('elevacao-de-pernas', 'Elevação de pernas', '{abdomen}', '{}', 'peso corporal', 'isolado', 'intermediario',
 '{"Deite com as pernas estendidas e as mãos ao lado do corpo ou sob o quadril.","Eleve as pernas até cerca de 90° mantendo a lombar apoiada.","Desça controlando sem encostar os pés no chão."}',
 '{"Flexione os joelhos para reduzir a dificuldade."}'),
('abdominal-polia', 'Abdominal na polia', '{abdomen}', '{}', 'polia', 'isolado', 'intermediario',
 '{"Ajoelhe-se de frente para a polia alta segurando a corda junto à cabeça.","Flexione o tronco aproximando as costelas do quadril.","Retorne controlando."}',
 '{"O quadril permanece fixo; o movimento é da coluna."}'),
-- CARDIO ----------------------------------------------------------------------
('esteira', 'Esteira', '{cardio}', '{quadriceps,panturrilhas}', 'esteira', null, 'iniciante',
 '{"Inicie com velocidade baixa para aquecimento.","Ajuste velocidade e inclinação conforme a orientação do treino.","Mantenha a postura ereta sem se apoiar nas barras laterais."}',
 '{"Use o clipe de segurança."}'),
('bicicleta-ergometrica', 'Bicicleta ergométrica', '{cardio}', '{quadriceps}', 'bicicleta', null, 'iniciante',
 '{"Ajuste a altura do banco para que o joelho fique levemente flexionado no ponto mais baixo do pedal.","Pedale mantendo a cadência e a carga indicadas no treino."}',
 '{}'),
('remo-ergometro', 'Remo ergômetro', '{cardio,costas}', '{quadriceps,biceps}', 'remo', 'composto', 'iniciante',
 '{"Prenda os pés e segure a manopla com os braços estendidos.","Empurre com as pernas, depois incline levemente o tronco e puxe a manopla até o abdômen.","Retorne na ordem inversa: braços, tronco e pernas."}',
 '{"A força principal vem das pernas."}')
on conflict (slug) do nothing;
